% Requires preamble: \usepackage{amsthm,amsmath,amssymb}
% and: \newtheorem{theorem}{Theorem}
%      \newtheorem{corollary}[theorem]{Corollary}
%      \newtheorem{proposition}[theorem]{Proposition}

\section{Bias Decomposition: When Debiasing Hurts}
\label{sec:theory}

We formalize the bias that global misclassification correction introduces when subgroup error rates are heterogeneous.
Consider estimating the conditional average treatment effect (CATE) $\tau(z) = \mathbb{E}[Y(1) - Y(0) \mid Z = z]$, where $Z \in \{0, 1\}$ is a binary effect modifier observed only through a noisy annotation $\hat{Z}$.
The population consists of $K$ subgroups $S \in \{1, \ldots, K\}$ with weights $w_s = P(S{=}s)$, each characterized by a $2 \times 2$ confusion matrix $C_s$ with symmetric error rate $\pi_s = P(\hat{Z} \neq Z \mid S{=}s)$.
Standard practice estimates a single confusion matrix $\bar{C} = \sum_s w_s C_s$ from expert annotations and applies its inverse uniformly to all observations, with pooled error rate $\bar{\pi} = \sum_s w_s \pi_s$.
We show that when error rates vary across subgroups, this global procedure introduces a bias with an exact product form.

We state five assumptions maintained throughout.
%
\begin{itemize}
\item[\textbf{(A1)}] \textit{Conditional independence:} misclassification depends only on the true label $Z$ and subgroup $S$, not on potential outcomes $Y(0), Y(1)$.
\item[\textbf{(A2)}] \textit{Symmetric misclassification (expository simplification):} $P(\hat{Z}{=}1 \mid Z{=}0, S{=}s) = P(\hat{Z}{=}0 \mid Z{=}1, S{=}s) = \pi_s$ for all $s$. Used only to reduce $[B_s]_{z,1}$ to the scalar $\pm\delta_s/(1{-}2\bar{\pi})$; the product-form identity holds for arbitrary asymmetric matrices without~(A2) (Remark~\ref{rem:asymmetric}).
\item[\textbf{(A3)}] \textit{Balanced effect modifier:} $P(Z{=}0) = P(Z{=}1) = 0.5$. This simplifies the exposition; we discuss relaxation below.
\item[\textbf{(A4)}] \textit{Non-degeneracy:} $\pi_s \neq 0.5$ for all $s$, ensuring each $C_s$ is invertible.
\item[\textbf{(A5)}] \textit{Homogeneous treatment effects across subgroups:} $\tau(z, s) = \tau(z)$ for all $s$, so $\Delta\tau = \tau(1) - \tau(0)$ is a scalar (relaxed to subgroup-specific $\Delta\tau_s$ in Proposition~\ref{prop:a5_relaxation}).
\end{itemize}

Under (A2)--(A3), the Bayesian mixing matrix $M_s$ (entries $M_s[\hat{z}, z] = P(Z{=}z \mid \hat{Z}{=}\hat{z}, S{=}s)$) coincides with $C_s$.
The global mixing matrix is $M_{\text{global}} = \sum_s w_s M_s$.

\begin{theorem}[Bias Decomposition Identity]
\label{thm:bias_identity}
Under \textnormal{(A1)--(A5)}, the bias of global correction in subgroup $s$ at effect-modifier level $z$ is
\begin{align}
\mathrm{bias}_{\mathrm{global}}(z{=}0, s) &= +\frac{\delta_s \cdot \Delta\tau}{1 - 2\bar{\pi}}, \label{eq:bias_z0} \\
\mathrm{bias}_{\mathrm{global}}(z{=}1, s) &= -\frac{\delta_s \cdot \Delta\tau}{1 - 2\bar{\pi}}, \label{eq:bias_z1}
\end{align}
where $\delta_s = \pi_s - \bar{\pi}$ is the subgroup deviation from the pooled error rate and $\Delta\tau = \tau(1) - \tau(0)$ is the CATE heterogeneity.
\end{theorem}

Bias vanishes when either $\delta_s = 0$ (homogeneous errors) or $\Delta\tau = 0$ (no effect heterogeneity), and arises only through their interaction; $1/(1 - 2\bar{\pi})$ amplifies via matrix inversion.
The identity is correction-layer: it characterizes bias introduced by the correction step itself, trading attenuation from label noise for a new bias from error-rate heterogeneity. Propagation to downstream estimators is verified empirically (Section~\ref{sec:bias_mechanism}).

\paragraph{Numerical example ($K{=}2$).}
Suppose two subgroups with $\pi_A = 0.05$, $\pi_B = 0.25$, giving $\bar{\pi} = 0.15$, and true CATEs $\tau(0) = 0.10$, $\tau(1) = 0.30$, so $\Delta\tau = 0.20$.
For subgroup $A$: $\delta_A = 0.05 - 0.15 = -0.10$, bias $= -0.10 \times 0.20 / 0.70 = -0.029$---global correction \emph{creates} bias in a subgroup where the naive estimator is nearly unbiased ($\pi_A = 0.05$).
For subgroup $B$: $\delta_B = +0.10$, bias $= +0.029$, partially offsetting attenuation. The opposite signs illustrate why aggregate metrics can mask subgroup-level harm.

\paragraph{Proof sketch.}
Global correction applies $M_{\text{global}}^{-1}$ to the subgroup-specific observed CATE $\tau_{\text{obs}}(\cdot, s) = M_s \cdot \tau_{\text{true}}$, yielding bias $(M_{\text{global}}^{-1} M_s - I) \cdot \tau_{\text{true}}$.
Direct computation shows $M_{\text{global}}^{-1} M_s - I = \frac{\delta_s}{1-2\bar{\pi}} \bigl[\begin{smallmatrix} -1 & 1 \\ 1 & -1 \end{smallmatrix}\bigr]$.
Applying this matrix to $[\tau(0),\, \tau(1)]^\top$ produces the product form.
The full derivation appears in Appendix~\ref{app:derivation}.
Unlike Frazis--Loewenstein scalar attenuation~\citep{frazis2003estimating}, which uniformly shrinks estimates toward zero ($K{=}1$: $\delta_s \equiv 0$ recovers $\hat{\beta} = (1-2\pi)\beta$), the product form reveals that correction can \emph{reverse} bias sign across subgroups---a qualitatively new phenomenon from error-rate heterogeneity invisible to any global-scalar analysis (F-L increases $|\text{bias}|$ to $0.122$, $2.1\times$ naive; Table~\ref{tab:main_results}).

\begin{remark}
\label{rem:asymmetric}
Theorem~\ref{thm:bias_identity} does not require assumption~(A2).
For arbitrary asymmetric confusion matrices where the false positive rate ($\mathrm{FPR}_s$) and false negative rate ($\mathrm{FNR}_s$) may differ,
the product form $\mathrm{bias}(z, s) = \Delta\tau \cdot [B_s]_{z,1}$ holds exactly,
where $B_s = M_{\mathrm{global}}^{-1} M_s - I$, because $B_s \mathbf{1} = \mathbf{0}$
follows from stochasticity of $M_s$ and $M_{\mathrm{global}}$ alone.
Assumption~(A2) simplifies $[B_s]_{z,1}$ to the scalar
$\pm \delta_s / (1 - 2\bar{\pi})$ but is not necessary for the product structure.
Under asymmetric errors, the scalar diagnostic (Proposition~\ref{prop:debiasing_hurts}) remains effective with $\pi_s = (\mathrm{FPR}_s + \mathrm{FNR}_s)/2$: the screening criterion achieves per-subgroup AUC $= 0.96$ across 48 asymmetric configurations (FPR/FNR ratios 1:5 to 5:1) and correctly identifies all harmed subgroups across 8 semi-real LLM confusion matrices (32 subgroups; Appendix~\ref{app:asymmetric}).
The criterion's validity extends beyond the symmetric case because the threshold $|\delta_s|/((1{-}2\bar{\pi})\pi_s) > 1$ is equivalent to $|B_s|/|D_s| > 1$ whenever subgroups have heterogeneous overall error rates.
\end{remark}

\begin{proposition}[Exact Identity under Heterogeneous Treatment Effects]
\label{prop:a5_relaxation}
When $\tau(z, s)$ varies across subgroups (relaxing A5), the bias identity remains exact:
\begin{align}
\mathrm{bias}_{\mathrm{global}}(z{=}0, s) &= +\frac{\delta_s \cdot \Delta\tau_s}{1 - 2\bar{\pi}}, \label{eq:hetero_z0} \\
\mathrm{bias}_{\mathrm{global}}(z{=}1, s) &= -\frac{\delta_s \cdot \Delta\tau_s}{1 - 2\bar{\pi}}, \label{eq:hetero_z1}
\end{align}
where $\Delta\tau_s = \tau_s(1) - \tau_s(0)$ is the subgroup-specific CATE heterogeneity.
\end{proposition}

\begin{corollary}[Aggregate Bias]
\label{cor:aggregate_bias}
The population-weighted aggregate bias is $\mathrm{Cov}_w(\pi_s, \Delta\tau_s) / (1 - 2\bar{\pi})$.
\end{corollary}

The proof is immediate: $B_s$ depends only on confusion matrices, so the diagnostic extends unchanged and EC-HTE maintains $\geq$93\% coverage under both correlation signs (Appendix~\ref{app:a5_violation}).

The identity extends to $K > 2$ with $J$ effect-modifier levels (Corollary~\ref{cor:multiclass}, Appendix~\ref{app:multiclass}).
Under class imbalance (relaxing A3), the identity remains exact with modified coefficients: $R^2 \geq 0.976$ and coverage $\geq$90\% even at $P(Z{=}1) = 0.1$ for $K{=}2$, though EC-HTE's RMSE ratio relative to global correction increases to 1.06--1.68 as imbalance grows (Appendix~\ref{app:classimbalance}).
Empirical verification yields $R^2 = 0.994$ ($K{=}2$) and $0.97$ ($K{=}4$; Section~\ref{sec:bias_mechanism}).

\paragraph{Sensitivity to (A1).}
Assumption~(A1) is not empirically testable; if misclassification correlates with potential outcomes, Theorem~\ref{thm:bias_identity} gains an $O(\gamma)$ perturbation.
At $\gamma_T = 0.10$, coverage degrades to 75\% (Appendix~\ref{app:treatment_dep}); sensitivity frameworks~\cite{lash2009applying,dorn2022sharp,cinelli2020making} can bound this.

\paragraph{Finite-sample remainder.}
With estimated $\hat{C}_s = C_s + E_s$, $\|E_s\| = O_p(n_{\text{expert}}^{-1/2})$, the remainder is $R_n = O_p(n_{\text{expert}}^{-1/2} \cdot \kappa(C_s)^2)$, where the squared condition number arises from the Neumann expansion $\hat{C}_s^{-1} = C_s^{-1} - C_s^{-1} E_s C_s^{-1} + O(\|E_s\|^2)$, motivating the $\kappa$-guard in Section~\ref{sec:method}.

\begin{proposition}[Debiasing Can Increase Bias]
\label{prop:debiasing_hurts}
Under \textnormal{(A1)--(A5)}, global correction produces larger absolute bias than the naive estimator ($|\mathrm{bias}_{\mathrm{global}}| > |\mathrm{bias}_{\mathrm{naive}}|$) in subgroup $s$ if and only if
\begin{equation}
\frac{|\delta_s|}{(1 - 2\bar{\pi}) \cdot \pi_s} > 1.
\label{eq:hurts_condition}
\end{equation}
\end{proposition}

\medskip
Equation~\eqref{eq:hurts_condition} partitions subgroups into two regimes:
\begin{itemize}
    \item \textit{High-error} ($\pi_s > \bar{\pi}$): the condition reduces to $\pi_s > 0.5$, excluded by~(A4); global correction always reduces bias.
    \item \textit{Low-error} ($\pi_s < \bar{\pi}$): the condition holds whenever $\pi_s < \bar{\pi} / (2(1 - \bar{\pi}))$---easily satisfied: when $\bar{\pi} = 0.15$, any subgroup with $\pi_s < 0.088$ is harmed by global correction.
\end{itemize}
The mechanism is over-correction: for subgroups with near-zero misclassification ($\pi_s \approx 0$), the naive estimator is nearly unbiased, yet global inversion calibrated for $\bar{\pi}$ creates substantial bias---debiasing is worse than doing nothing, and can reverse bias sign across subgroups.

In our experiments (Section~\ref{sec:bias_mechanism}), global correction increases bias in 50\% of $K{=}2$ configurations (260/520), with amplification reaching $2.86\times$ ($K{=}2$) and $2.41\times$ ($K{=}4$); Figure~\ref{fig:heatmap} visualizes the full parameter grid.

\begin{figure*}[t]
\centering
\includegraphics[width=\textwidth]{figures/fig_method_overview.pdf}
\caption{\textit{Top (rose):} global correction applies a pooled confusion matrix uniformly, risking sign reversal. \textit{Bottom (teal):} EC-HTE estimates per-subgroup matrices via hierarchical Bayes, applies stratified inversion with a $\kappa$-guard, and propagates uncertainty into CausalForestDML.}
\label{fig:method_overview}
\end{figure*}

\section{Experiments}

\begin{figure}[t]
\centering
\includegraphics[width=\columnwidth]{figures/fig4_budget_compact.pdf}
\caption{RMSE vs.\ expert budget under extreme heterogeneity. Crossover at $n{=}250$ ($K{=}2$) and $n{=}1000$ ($K{=}4$); shaded bands: $\pm 1$ SD across subgroups. Full grid in Appendix~\ref{app:budget}.}
\label{fig:budget_compact}
\end{figure}

\subsection{Setup}

We test on synthetic ($N{=}5{,}000$, $K \in \{2, 4\}$, controlled $\Delta\tau$ and $\Delta\pi$, 100 Monte Carlo (MC) runs) and semi-synthetic data-generating processes (DGPs) spanning four NLP tasks---sentiment analysis (TweetEval~\cite{barbieri2020tweeteval}, $K{=}4$), hate speech detection (CivilComments, $K{=}4$), stance detection ($K{=}5$; Appendix~\ref{app:stance}), and topic classification (AG News, $K{=}4$; Appendix~\ref{app:agnews})---with full specifications in Appendix~\ref{app:dgp}.

We compare: (1) \textit{Naive} (no correction), (2) \textit{Global} (pooled confusion matrix, equivalent to PPI/DSL~\cite{angelopoulos2023ppi,egami2023dsl} with homogeneous error), (3) \textit{Stratified MLE} (per-subgroup DSL without shrinkage), (4) \textit{HB EC-HTE} (per-subgroup correction), (5) \textit{PPCI}~\cite{sui2026ppci}, and (6) \textit{EC-HTE+PPCI}.
For CausalForest~\cite{wager2018causal}, we compare naive, global, and EC-HTE variants.
Primary metrics are $|\text{bias}|$, root mean squared error (RMSE), and 95\% confidence interval (CI) coverage, averaged across subgroups and 100 MC runs.
Robustness validations cover eight conditions including asymmetric errors, subgroup misspecification, and treatment-dependent misclassification (all $\geq$89.5\% coverage; Appendices~\ref{app:hatespeech}--\ref{app:treatment_dep}).
Semi-synthetic evaluation uses 16 empirical LLM confusion matrices (8 LLMs $\times$ 2 datasets; Appendix~\ref{app:semireal}).

\subsection{Empirical Validation of the Bias Identity}
\label{sec:bias_mechanism}

\begin{figure*}[t]
\centering
\includegraphics[width=\textwidth]{figures/fig2_heatmap.pdf}
\caption{Bias amplification under global correction ($K{=}2$). (a)~Low-error subgroup: correction always helps. (b)~High-error subgroup: correction \emph{increases} bias when $\Delta\pi > 0.12$ (hatched), reaching $2.86\times$.}
\label{fig:heatmap}
\end{figure*}

We verify Theorem~\ref{thm:bias_identity} on a $K{=}2$ grid (520 configurations, $\Delta\pi \in [0, 0.25]$, $\Delta\tau \in (0, 0.50]$) and a $K{=}4$ grid (Appendix~\ref{app:dgp}).
Regressing observed subgroup bias on $\delta_s \cdot \Delta\tau / (1{-}2\bar{\pi})$ yields $R^2 = 0.994$ ($K{=}2$) and $0.97$ ($K{=}4$); residual variance reflects MC noise ($R^2 \geq 0.976$ even at $P(Z{=}1) = 0.1$; Appendix~\ref{app:classimbalance}).
Global correction worsens bias in 50\% of $K{=}2$ configurations (260/520, excluding $\Delta\pi{=}0$), with amplification reaching 2.86$\times$ ($K{=}2$) and 2.41$\times$ ($K{=}4$); Figure~\ref{fig:heatmap} visualizes the amplification surface.
Global correction also reverses the sign of estimated CATE in 14.9\% of configurations at $\tau(0) = 0.03$, with all eight real LLMs amplifying bias; EC-HTE eliminates sign reversal (Figure~\ref{fig:sign_reversal}; Appendix~\ref{app:policy_reversal}).
Cross-task validation on stance detection ($K{=}5$, Appendix~\ref{app:stance}) confirms sign reversal (13.3\% $\to$ 3.3\%) and reveals limitations when FNR${}>0.50$.
On CivilComments hate speech detection, the bias identity changes the substantive NLP conclusion: global correction suggests demographic-group moderation effects are uniformly small, while EC-HTE reveals a 3.2$\times$ effect-size gap between identity subgroups---consistent with known annotation disparities~\cite{borkan2019nuanced} (Appendix~\ref{app:hatespeech}).

\subsection{Correction Evaluation}
\label{sec:ec_hte_eval}

Table~\ref{tab:main_results} presents the main results.
In the $K{=}2$ extreme row, global correction \emph{increases} $|\text{bias}|$ relative to naive (0.059 vs.\ 0.058), confirming Theorem~\ref{thm:bias_identity}; F-L corrections fare worse (0.122--0.168).
HB EC-HTE reduces $|\text{bias}|$ from 0.059 to 0.008 (7.4$\times$); relative to stratified MLE (0.012), the advantage is 1.5$\times$ with lower RMSE from partial pooling. At $K{=}4$, bias reduces from 0.056 to 0.012 (4.7$\times$), maintaining near-nominal coverage (0.94--0.96).
Under moderate heterogeneity, methods converge ($p > 0.05$; Table~\ref{tab:main_supp}).
EC-HTE requires $n_{\text{expert}}/K \geq 50$; below this, RMSE exceeds global (Figure~\ref{fig:budget_compact}; Appendix~\ref{app:k8_subgroups}).

\paragraph{CausalForest.}
CausalForest~\cite{wager2018causal} with a noisy $\hat{Z}$ inherits the same $M_{\text{global}}^{-1} M_s$ structure.
EC-HTE reduces $|\text{bias}|$ from 0.191 to 0.039 (4.9$\times$) with coverage 0.90 ($K{=}4$, $n{=}500$); R-learner yields comparable reduction (89\%, Appendix~\ref{app:rlearner}), confirming the bias arises from the confusion matrix structure, not the downstream estimator.

